 async Task ToggleAnimationTimeline(){if(animationEditing){CloseAnimationTimeline();await Display();}else await OpenAnimationTimeline();}

 async Task SyncAnimationSelection(){if(!animationEditing||ActiveTrack==null)return;selectionSync=true;try{objects.SelectedItems.Clear();if(objects.Items.Contains(ActiveTrack.Mesh))objects.SelectedItem=ActiveTrack.Mesh;}finally{selectionSync=false;}await SyncViewportSelection();}
 void ResolveAnimationTarget(string mesh){BindAnimationIdentities();int clip=ActiveClip?.Tracks.Any(t=>t.Mesh==mesh)==true?animationIndex:Array.FindIndex(animationClips,c=>c.Tracks.Any(t=>t.Mesh==mesh));if(clip>=0){animationIndex=clip;animationTrack=Array.FindIndex(ActiveClip!.Tracks,t=>t.Mesh==mesh);animationPose=ActiveTrack!.Sample((float)animationFrame.Value);}else{animationTrack=-1;animationPose=AnimationPose.Identity;}}
