 void RenameAnimationMesh(string previous,string next){animationClips=animationClips.Select(c=>c with{Tracks=c.Tracks.Select(t=>t with{Mesh=t.Mesh==previous?next:t.Mesh,CargoParent=t.CargoParent==previous?next:t.CargoParent}).ToArray()}).ToArray();}
