 void RefreshAnimationTracks(){animationAxisSource.Text=UiLanguage.Text("Источник оси")+": "+UiLanguage.Text(ActiveTrack?.PivotSource switch{"Object"=>"Pivot объекта","Mechanism"=>"Ось механизма",_=>"Пользовательская ось"});animationUpdating=true;if(animationAxisChoice!=null)animationAxisChoice.IsChecked=animationAxisEditing;animationClipChoice.ItemsSource=animationClips.Select(c=>c.Name).ToArray();animationClipChoice.SelectedIndex=animationIndex;animationTracks.ItemsSource=ActiveClip?.Tracks.Select(t=>t.Mesh).ToArray();animationTracks.SelectedIndex=animationTrack;animationFrame.Maximum=ActiveClip?.LastFrame??100;if(animationCargoParent!=null)animationCargoParent.IsChecked=ActiveTrack?.CargoParent==ActiveTrack?.Mesh;if(animationFps!=null)animationFps.Value=ActiveClip?.Fps??30;if(animationDuration!=null)animationDuration.Value=ActiveClip?.LastFrame??100;if(animationCurve!=null)animationCurve.SelectedIndex=ActiveTrack?.Interpolation=="Linear"?1:0;if(animationAction!=null){animationAction.Items.Clear();string script=VehicleTemplate();foreach(var action in AnimationBindings.Actions.Where(a=>AnimationBindings.AppliesToScript(a.Key,script))){var item=new ComboBoxItem{Content=UiLanguage.Text(action.Label),Tag=action.Key};animationAction.Items.Add(item);if(action.Key==ActiveClip?.Action)animationAction.SelectedItem=item;}}animationUpdating=false;DrawAnimationGraph();}
