 void ReceiveAnimationFrame(JsonElement message){if(!animationEditing||ActiveClip==null||ActiveTrack==null||!message.TryGetProperty("animationFrame",out var value)||!value.TryGetSingle(out float frame)||!float.IsFinite(frame))return;animationUpdating=true;animationFrame.Value=Math.Clamp(frame,0,ActiveClip.LastFrame);animationPose=ActiveTrack.Sample(frame);animationUpdating=false;animationTime.Text=Math.Round(frame).ToString()+" / "+ActiveClip.LastFrame;}
