 void DrawAnimationGraph()
 { DrawTimelineKeys();
  if(animationEditing&&ActiveTrack==null){animationGraph.Children.Clear();animationTime.Text=UiLanguage.Text("Добавьте выбранный объект в анимацию кнопкой +");return;}if(ActiveClip!=null)animationTime.Text=Math.Round(animationFrame.Value).ToString()+" / "+ActiveClip.LastFrame;var track=ActiveTrack;if(track==null){animationGraph.Children.Clear();drawnGraphTrack=null;return;}double w=Math.Max(1,animationGraph.ActualWidth),h=animationGraph.Height;if(ReferenceEquals(track,drawnGraphTrack)&&drawnGraphChannel==animationGraphChannel.SelectedIndex&&drawnGraphLength==ActiveClip!.LastFrame&&drawnGraphWidth==w&&drawnGraphHeight==h)return;drawnGraphTrack=track;drawnGraphChannel=animationGraphChannel.SelectedIndex;drawnGraphLength=ActiveClip!.LastFrame;drawnGraphWidth=w;drawnGraphHeight=h;animationGraph.Children.Clear();var sample=track.Sampler();float[] Values(AnimationPose pose)=>animationGraphChannel.SelectedIndex switch{0=>pose.Position,2=>pose.Scale,_=>pose.Rotation};float[] all=track.Keys.SelectMany(k=>Values(k.Pose)).ToArray();double lo=Math.Min(0,all.Min()),hi=Math.Max(1,all.Max());var colours=new[]{Colors.IndianRed,Colors.MediumSeaGreen,Colors.CornflowerBlue};
  for(int axis=0;axis<3;axis++){var line=new Polyline{Stroke=new SolidColorBrush(colours[axis]),StrokeThickness=1.5};for(int i=0;i<=100;i++){float frame=ActiveClip!.LastFrame*i/100f;line.Points.Add(new(w*i/100,(h-12)*(1-(Values(sample(frame))[axis]-lo)/(hi-lo))+6));}animationGraph.Children.Add(line);}
  foreach(var k in track.Keys.Where((_,i)=>track.Keys.Length<=128||i%Math.Max(1,track.Keys.Length/126)==0||i==track.Keys.Length-1)){var point=new Button{Content=k.Frame.ToString(),Padding=new Thickness(3,0,3,0),MinWidth=0,MinHeight=0};Canvas.SetLeft(point,Math.Clamp(w*k.Frame/ActiveClip!.LastFrame-12,0,Math.Max(0,w-30)));Canvas.SetTop(point,h-24);point.Click+=(_,_)=>animationFrame.Value=k.Frame;animationGraph.Children.Add(point);}
